#!/usr/bin/env python3
"""Port-check a host list; exit 2 on any open unexpected port."""
import socket, sys
EXPECTED = {22, 443}
for host in sys.argv[1:]:
    for port in range(1, 1025):
        s = socket.socket(); s.settimeout(0.5)
        try:
            if s.connect_ex((host, port)) == 0 and port not in EXPECTED:
                print(f"UNEXPECTED: {host}:{port}")
                sys.exit(2)
        finally:
            s.close()
print("OK: no unexpected ports")
